WITH flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_burst FROM payments), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT id, order_id, paid_at, status, is_new_burst, CASE WHEN status RLIKE '^(SUCCESS|REFUNDED)$' THEN 'CORE' WHEN status RLIKE '^(FAILED)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS status_zone FROM sessionized ORDER BY order_id DESC NULLS FIRST;
